def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((agent_id, opp))

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.35))

    pressure_bid = 0.0
    cindy_bid = None
    starving_threats = 0
    rich_threats = 0

    for agent_id, opp in alive:
        prev = opp.get('previous_trace', {})
        pbid = prev.get('bid') if prev else None
        if pbid is not None:
            if pbid > pressure_bid:
                pressure_bid = pbid
            if agent_id == 'Cindy':
                cindy_bid = pbid
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 0) <= 3:
            starving_threats += 1
        if opp.get('budget', 0) >= budget * 0.9:
            rich_threats += 1

    tight_supply = supply <= 17
    medium_supply = supply <= 20

    base = DAILY_SALARY * 0.42

    if tight_supply:
        base = DAILY_SALARY * 0.72
    elif medium_supply:
        base = DAILY_SALARY * 0.56

    if hp <= 2 or no_water_days >= 1:
        base = max(base, DAILY_SALARY * 0.9)
    elif hp <= 4:
        base = max(base, DAILY_SALARY * 0.68)

    if cindy_bid is not None:
        if cindy_bid >= 180:
            if hp > 4 and not tight_supply:
                base = min(base, DAILY_SALARY * 0.38)
            else:
                base = max(base, DAILY_SALARY * 0.88)
        elif cindy_bid >= 130:
            base = max(base, min(DAILY_SALARY * 0.82, cindy_bid * 0.62))
        else:
            base = max(base, cindy_bid + 3.0)
    elif pressure_bid > 0:
        if pressure_bid >= 100:
            if hp > 4 and not tight_supply:
                base = min(base, DAILY_SALARY * 0.4)
            else:
                base = max(base, DAILY_SALARY * 0.8)
        else:
            base = max(base, pressure_bid + 2.0)

    if starving_threats >= 2 and hp > 3 and not tight_supply:
        base *= 0.9
    if rich_threats >= 2 and medium_supply:
        base *= 1.08

    if day >= 8:
        if hp <= 4:
            base = max(base, DAILY_SALARY * 0.82)
        else:
            base = max(base, DAILY_SALARY * 0.58)

    bid = min(budget, base)
    if budget <= DAILY_SALARY * 0.6 and hp > 3 and not tight_supply:
        bid = min(bid, budget * 0.75)

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = int(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_ids = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_ids.append(oid)

    if not alive_ids:
        return float(min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace
    prev_bids = []
    prev_by_id = {}
    for oid in alive_ids:
        tr = opponents_status[oid].get('previous_trace', {})
        bid = tr.get('bid', None)
        if bid is not None:
            try:
                bid_val = float(bid)
            except Exception:
                continue
            prev_bids.append(bid_val)
            prev_by_id[oid] = bid_val

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Identify likely aggressor: highest yesterday bid among alive
    aggressor_bid = highest_prev_bid
    aggressor_id = None
    if prev_bids:
        for oid in alive_ids:
            if oid in prev_by_id and prev_by_id[oid] == aggressor_bid:
                aggressor_id = oid
                break

    # Supply pressure: if supply is near max, we can afford to bid less; if near min, bidding is more valuable.
    # Convert to a 0..1 pressure factor.
    if MAX_SUPPLY == MIN_SUPPLY:
        pressure = 0.5
    else:
        pressure = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
        if pressure < 0.0:
            pressure = 0.0
        if pressure > 1.0:
            pressure = 1.0

    # Our need: if we're close to death, we must secure water.
    urgent = (my_hp <= 2) or (my_no_water_days >= 2)

    # Baseline bid depends on HP; also counter Cindy-like behavior by checking if highest_prev_bid was high.
    high_threat = aggressor_bid >= DAILY_SALARY * 0.75

    # Choose target bid.
    if urgent:
        # Spend to survive; outbid likely aggressor if they were strong.
        if high_threat:
            target = aggressor_bid + 5.0
        else:
            target = DAILY_SALARY * 0.85
    else:
        if high_threat:
            # Cindy-like: don't blindly overpay; bid just enough to avoid losing the water allocation.
            # If our HP is moderate, we can slightly undercut.
            if my_hp >= 6:
                target = min(aggressor_bid + 2.0, DAILY_SALARY * (0.55 + 0.2 * pressure))
            else:
                target = min(aggressor_bid + 3.5, DAILY_SALARY * (0.65 + 0.2 * pressure))
        else:
            # No strong aggressor: bid conservatively, scaled by pressure.
            target = DAILY_SALARY * (0.45 + 0.25 * pressure)

    # Ensure we never bid more than budget.
    if my_budget <= 0.0:
        return 0.0

    bid = float(min(my_budget, max(0.0, target)))

    # If supply is low and we are not urgent, still ensure some participation.
    if supply <= float(WATER_REQ) + 6.0 and bid < DAILY_SALARY * 0.35 and my_hp >= 4:
        bid = float(min(my_budget, DAILY_SALARY * 0.4))

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    TOTAL_DAYS = 10

    current_day = day_context['day']
    current_supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    my_no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_budget, DAILY_SALARY * 0.1)

    remaining_days = TOTAL_DAYS - current_day + 1

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0
    average_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0

    base_bid = DAILY_SALARY * 0.5

    if my_hp <= 2:
        base_bid = DAILY_SALARY * 0.95
    elif my_hp <= 4:
        base_bid = DAILY_SALARY * 0.8
    elif my_hp <= 6:
        base_bid = DAILY_SALARY * 0.65
    else:
        base_bid = DAILY_SALARY * 0.45

    if remaining_days <= 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.9)
    elif remaining_days <= 4:
        base_bid = max(base_bid, DAILY_SALARY * 0.7)

    num_slots = int(current_supply // WATER_REQ)

    if num_slots == 0:
        return min(my_budget, DAILY_SALARY * 0.1)
    elif num_slots == 1:
        base_bid = max(base_bid, DAILY_SALARY * 0.8)
    elif num_slots == 2 and num_alive_opponents >= 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.6)
    elif num_slots > num_alive_opponents + 1:
        base_bid = min(base_bid, DAILY_SALARY * 0.3)

    if highest_prev_bid > 0:
        if my_hp <= 3 or my_no_water_days > 0:
            base_bid = max(base_bid, highest_prev_bid * 1.05)
        elif highest_prev_bid >= DAILY_SALARY * 0.8:
            base_bid = max(base_bid, highest_prev_bid * 1.02)
        elif average_prev_bid > DAILY_SALARY * 0.4:
            base_bid = max(base_bid, average_prev_bid + 5)

    final_bid = min(my_budget, base_bid)

    if my_hp <= 5 or my_no_water_days > 0:
        final_bid = max(final_bid, DAILY_SALARY * 0.2)

    final_bid = max(0.0, final_bid)

    return final_bid

